from pathlib import Path
import json,numpy as np,sys
n=Path(sys.argv[1]);r=json.loads((n/'s9-n3-phase-fields.json').read_text());fs={(f['stage'],f['role']):f for f in r['frames']};a=np.fromfile(n/fs['after-fine-before-brush','pigment']['file'],dtype=np.uint8).astype(np.int16).reshape(-1,4);b=np.fromfile(n/fs['after-brush-stable','pigment']['file'],dtype=np.uint8).astype(np.int16).reshape(-1,4);delta=b-a;out={'changedPhysicalPixels':int((delta!=0).any(axis=1).sum()),'changedByChannel':(delta!=0).sum(axis=0).tolist(),'sumAbsoluteByteDeltaRGBA':abs(delta).sum(axis=0).tolist(),'sumAbsoluteOverInitialRGBA':(abs(delta).sum(axis=0)/np.maximum(1,a.sum(axis=0))).tolist(),'netByteDeltaRGBA':delta.sum(axis=0).tolist()};(n/'integer-motion-audit.json').write_text(json.dumps(out,indent=2));print(json.dumps(out))
